   175	/// Database of C/C++ type information extracted from clang.
   176	///
   177	/// Built from `compile_commands.json` by running clang on each translation unit
   178	/// and parsing the JSON AST dump.
   179	#[derive(Debug, Default, Clone)]
   180	pub struct TypeDatabase {
   181	    /// Record (struct/class/union) definitions by name.
   182	    pub records: BTreeMap<String, RecordInfo>,
   183	    /// Typedef/alias mappings: alias name → TypedefInfo.
   184	    pub typedefs: BTreeMap<String, TypedefInfo>,
   185	    /// Class hierarchy: class name → list of direct base class names.
   186	    pub class_hierarchy: BTreeMap<String, Vec<String>>,
   187	}
