   189	impl TypeDatabase {
   190	    /// Build a TypeDatabase from a `compile_commands.json` file.
   191	    ///
   192	    /// For each translation unit in the compile commands:
   193	    /// 1. Run `clang -fsyntax-only -Xclang -ast-dump=json` with the same flags
   194	    /// 2. Parse the JSON AST dump
   195	    /// 3. Extract struct/class/union definitions, typedefs, and class hierarchy
   196	    ///
   197	    /// Files not in `filter_files` (if provided) are skipped for efficiency.
   198	    pub fn from_compile_commands(
   199	        compile_commands_path: &Path,
   200	        filter_files: Option<&[&str]>,
   201	    ) -> Result<Self> {
   202	        let content = std::fs::read_to_string(compile_commands_path)
   203	            .with_context(|| format!("reading {}", compile_commands_path.display()))?;
   204	
   205	        let commands: Vec<CompileCommand> =
   206	            serde_json::from_str(&content).with_context(|| "parsing compile_commands.json")?;
   207	
   208	        let mut db = TypeDatabase::default();
   209	
   210	        for cmd in &commands {
   211	            // Skip files not in our filter set
   212	            if let Some(filter) = filter_files {
   213	                let file_name = Path::new(&cmd.file)
   214	                    .file_name()
   215	                    .and_then(|n| n.to_str())
   216	                    .unwrap_or("");
   217	                let matches = filter
   218	                    .iter()
   219	                    .any(|f| cmd.file.ends_with(f) || file_name == *f);
   220	                if !matches {
   221	                    continue;
   222	                }
   223	            }
   224	
   225	            // Run clang to get JSON AST
   226	            match run_clang_ast_dump(cmd) {
   227	                Ok(ast_json) => {
   228	                    if let Err(e) = db.extract_from_ast(&ast_json, &cmd.file) {
   229	                        eprintln!("warning: type extraction failed for {}: {}", cmd.file, e);
   230	                    }
   231	                }
   232	                Err(e) => {
   233	                    eprintln!("warning: clang AST dump failed for {}: {}", cmd.file, e);
   234	                }
   235	            }
   236	        }
   237	
   238	        // Build class hierarchy from base class info
   239	        for record in db.records.values() {
   240	            if !record.bases.is_empty() {
