   392	    /// Resolve a typedef chain to its canonical underlying type.
   393	    ///
   394	    /// Follows typedef chains up to a depth limit to prevent infinite loops.
   395	    pub fn resolve_typedef(&self, name: &str) -> String {
   396	        let mut current = name.to_string();
   397	        for _ in 0..10 {
   398	            match self.typedefs.get(&current) {
   399	                Some(td) => current = td.underlying.clone(),
   400	                None => break,
   401	            }
   402	        }
   403	        current
   404	    }
