   406	    /// Get the record (struct/class/union) for a type name, resolving typedefs.
   407	    pub fn resolve_record(&self, type_name: &str) -> Option<&RecordInfo> {
   408	        // Try direct lookup first
   409	        if let Some(record) = self.records.get(type_name) {
   410	            return Some(record);
   411	        }
   412	
   413	        // Resolve typedefs
   414	        let resolved = self.resolve_typedef(type_name);
   415	
   416	        // Strip pointer/reference qualifiers: "struct device *" → "device"
   417	        let stripped = strip_type_qualifiers(&resolved);
   418	
   419	        self.records.get(stripped)
   420	    }
