   422	    /// Get all fields of a record type (struct/class/union), including
   423	    /// inherited fields from base classes.
   424	    pub fn all_fields(&self, record_name: &str) -> Vec<FieldInfo> {
   425	        let mut fields = Vec::new();
   426	        let mut visited = std::collections::BTreeSet::new();
   427	        self.collect_fields(record_name, &mut fields, &mut visited);
   428	        fields
   429	    }
   430	
   431	    fn collect_fields(
   432	        &self,
   433	        name: &str,
   434	        fields: &mut Vec<FieldInfo>,
   435	        visited: &mut std::collections::BTreeSet<String>,
   436	    ) {
   437	        if !visited.insert(name.to_string()) {
   438	            return;
   439	        }
   440	
   441	        if let Some(record) = self.records.get(name) {
   442	            // First add inherited fields from base classes
   443	            for base in &record.bases {
   444	                self.collect_fields(base, fields, visited);
   445	            }
   446	            // Then add own fields
   447	            fields.extend(record.fields.iter().cloned());
   448	        }
   449	    }
