    93	/// Normalize an owner type's source text to its bare index key:
    94	/// strip refs/pointers, smart-pointer wrappers are NOT peeled here (that is
    95	/// receiver peeling, `peel_type`), strip generic args, strip `dyn `/`impl `.
    96	pub fn owner_key(text: &str) -> String {
    97	    let t = text.trim();
    98	    let t = t.trim_start_matches("&mut ").trim_start_matches('&');
