   138	/// Arity admission for interface-dispatch candidates (language-neutral; shared by
   139	/// the resolution mint and the `interface_dispatch_manifest`). CONSERVATIVE on
   140	/// purpose — the headline risk is recall loss (dropping a valid dispatch edge), so
   141	/// a candidate is dropped ONLY on a confident exact mismatch and EVERY unknown
   142	/// keeps it:
   143	///   * a variadic candidate is never dropped (`a.variadic`),
   144	///   * a spread call (`arg_spread`) drops nothing,
   145	///   * an unknown `arg_count` (`None`) drops nothing,
   146	///   * a candidate with no recorded `MethodArity` (`m == None`) is never dropped.
   147	/// Only a known, non-spread call against a known, non-variadic method with a
   148	/// different param count is provably-wrong and dropped.
   149	pub fn arity_admits(arg_count: Option<usize>, arg_spread: bool, m: Option<&MethodArity>) -> bool {
   150	    match (arg_count, m) {
   151	        // Drop ONLY on a confident exact mismatch:
   152	        (Some(n), Some(a)) if !arg_spread && !a.variadic => a.params == n,
   153	        // Every unknown keeps the candidate (recall-safe):
   154	        _ => true,
   155	    }
   156	}
