   175	pub fn peel_type(text: &str) -> String {
   176	    let mut t = text.trim();
   177	    loop {
   178	        let before = t;
   179	        t = t
   180	            .trim_start_matches("&mut ")
   181	            .trim_start_matches('&')
   182	            .trim_start_matches("*const ")
   183	            .trim_start_matches("*mut ")
   184	            .trim_start_matches('*')
   185	            .trim();
   186	        // Rust lifetime after a reference: `&'a Sender` / `&'a mut Sender`.
   187	        // Drop a leading `'lifetime` token (and an optional following `mut`).
   188	        if let Some(rest) = t.strip_prefix('\'') {
   189	            let rest = rest.trim_start_matches(|c: char| c.is_alphanumeric() || c == '_');
