   374	/// Recover the statically-asserted type from a Go `x.(T).M()` call.
   375	///
   376	/// The grammar for `type_assertion_expression` (tree-sitter-go §primary):
   377	/// `operand '.' '(' type ')'`. The `type` field is any `_type`, including
   378	/// `parenthesized_type` (`(T)`), `pointer_type` (`*T`), `qualified_type`
   379	/// (`pkg.T`), or `type_identifier` (`T`).
   380	///
   381	/// Normalization:
   382	/// - `parenthesized_type` is unwrapped one level at a time.
   383	/// - `peel_type` strips `*` (pointer); `owner_key` strips the remaining `::` paths.
   384	/// - `pkg.T` is NOT stripped here — `iface_key` handles that at route time in
   385	///   `resolve_call_site` so owner-lookup routes correctly for concrete types too.
   386	///
   387	/// Deferred gap (D2): cross-package concrete `pkg.T` where `T` is not an interface
   388	/// will fail `owner_lookup` (key `"pkg.T"` has no owner entry). Recorded in spec §D2.
   389	fn recover_type_assertion(ctx: &ReceiverCtx<'_>) -> Option<RecoveredReceiver> {
   390	    use crate::languages::Language;
   391	    if ctx.parsed.language != Language::Go {
   392	        return None;
   393	    }
   394	    let node = ctx.receiver_expr?;
   395	    if node.kind() != "type_assertion_expression" {
   396	        return None;
   397	    }
   398	    let mut ty = node.child_by_field_name("type")?;
   399	    // Unwrap parenthesized_type: `(T)` → `T` (handles `x.((Runner)).M()`)
   400	    while ty.kind() == "parenthesized_type" {
   401	        ty = ty.named_child(0)?;
   402	    }
   403	    // Same normalization as the legacy path → consistent routing: an interface
   404	    // (`Runner`/`pkg.Module`) routes via iface_key→interface_impls; a same-package
   405	    // concrete (`*Fast`) owner_lookup-resolves. Cross-package concrete `pkg.T`
   406	    // does NOT owner-resolve (owner_key keeps `pkg.`) — deferred gap D2.
   407	    let static_type = owner_key(&peel_type(ctx.parsed.node_text(&ty)));
   408	    if static_type.is_empty() {
   409	        return None;
   410	    }
   411	    Some(RecoveredReceiver {
   412	        static_type,
   413	        recovery: ReceiverRecovery::TypeAssertion,
   414	    })
   415	}
